  // Ein einzelner Barren - so bleibt Silber von Gold unterscheidbar.
  SILVER: '<g fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round">'
    + '<path d="M10.4 9.4h15.2l2.4 8.6H8Z"/><path d="M12.6 13.4h13.4" stroke-width="1.1" opacity=".6"/></g>',
  // Tropfen.
  OIL: '<path d="M18 3.2c4.8 6 7.7 9.8 7.7 13.1a7.7 7.7 0 0 1-15.4 0c0-3.3 2.9-7.1 7.7-13.1Z" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/>'
    + '<path d="M14.6 16.4a3.4 3.4 0 0 0 2.2 3" fill="none" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" opacity=".55"/>',
  // Muenze mit Bitcoin-Zeichen.
  BTC: '<circle cx="18" cy="12" r="8.8" fill="none" stroke="currentColor" stroke-width="1.9"/>'
    + '<path d="M15 7.8h4.2c2.1 0 3.3 1 3.3 2.5 0 1-.6 1.7-1.6 2 1.3.3 2.1 1.1 2.1 2.4 0 1.7-1.4 2.6-3.6 2.6H15Z" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linejoin="round"/>'
    + '<path d="M17.2 5.4v2.6M20.2 5.4v2.6M17.2 16.6v2.6M20.2 16.6v2.6" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/>',
  ETH: '<path d="M18 3 26.2 12 18 16.6 9.8 12Z" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linejoin="round"/>'
