// Rohstoffe/Krypto/Indizes (NONFX_IDS) haben kein eigenes Land/keine eigene
// Notenbank, hängen aber am USD-Makrozyklus (siehe macroCcyFor) - sie
// teilen sich daher dieselben Recherche-Daten/Quellenlinks wie USD.
NONFX_IDS.forEach(id=>{IND_RESEARCH_DATA[id]=IND_RESEARCH_DATA.USD;});
const RESEARCH_MONTHS_DE_FULL=['January','February','March','April','May','June','July','August','September','October','November','December'];
// Volles Datum für die Quellenangabe im aufklappbaren Indikator-Detail.
function fmtResearchDateFull(s){
  if(!s)return'';
  const d=new Date(s+'T00:00:00');
  if(isNaN(d))return'';
  return`${d.getDate()}. ${RESEARCH_MONTHS_DE_FULL[d.getMonth()]} ${d.getFullYear()}`;
}
// Kurzer, lesbarer Domainname für den "Quelle ↗"-Link.
function srcLabel(url){
  let host;
  try{host=new URL(url).hostname.replace(/^www\./,'');}catch(e){return'Source';}
  // Zeigt die verlinkte Quelle einen MONATS-Wert (m/m)? Dann sichtbar an den
  // Link schreiben, damit klar ist, dass die Seite KEINEN y/y-Wert zeigt. Die
  // meisten investing.com-Seiten tragen "mom" im Slug; einige nicht (z.B. die
  // kanadische/australische Retail-Sales-MoM-Seite retail-sales-260/-262, die
  // es dort nicht als y/y-Variante gibt) - diese sind explizit gelistet.
  const u=String(url).toLowerCase();
  const isMoM=/\bmom\b|-mom-|\(mom\)|mom-\d|\/retail-sales-260\b|\/retail-sales-262\b/.test(u);
  return isMoM?host+' (m/m)':host;
}
// Erkennt Zeitraum-Kürzel (y/y, m/m, q/q in jeder Schreibweise) und liefert
// die normalisierte Anzeigeform ("Y/Y"/"M/M"/"Q/Q").
const PERIOD_TAG_RE=/Y\/Y|YoY|y\/y|M\/M|MoM|m\/m|Q\/Q|QoQ|q\/q/;
function periodLabel(tag){
  const t=(tag||'').toLowerCase();
  if(/y\/y|yoy/.test(t))return'Y/Y';
  if(/m\/m|mom/.test(t))return'M/M';
  if(/q\/q|qoq/.test(t))return'Q/Q';
  return null;
}
// Entfernt ein von applyIndResearch angehängtes Zeitraum-Kürzel
// (" y/y"/" m/m"/" q/q") vom Indikator-Namen, damit Kalender-Matching und
// Migration weiterhin auf dem Basisnamen arbeiten. Liefert zusätzlich das
// erkannte Zeitraum-Kürzel zurück (für die Kalender-Event-Filterung).
const NAME_PERIOD_SUFFIX_RE=/\s+(y\/y|m\/m|q\/q)$/i;
// Memoisiert (Performance-Fix 2026-07-19): stripPeriodSuffix ist eine REINE
// Funktion des Namens-Strings (haengt nur von NAME_PERIOD_SUFFIX_RE +
// periodLabel ab, beide konstant) und wird auf sehr heissen Pfaden extrem oft
// mit denselben ~dutzenden Indikatornamen aufgerufen (symTrackedCount ->
// fxRefCount -> symScoreCmp lief ~36.000 Regex-Matches pro renderDash). Cache
// nach Name; das Ergebnis wird eingefroren, weil es geteilt zurueckgegeben
// wird und Aufrufer nur .base/.period lesen. Cache-Groesse ist durch die
// endliche Zahl vorkommender Indikatornamen beschraenkt.
const _stripPeriodCache=new Map();
function stripPeriodSuffix(name){
  const key=name||'';
  const hit=_stripPeriodCache.get(key);
  if(hit)return hit;
  const m=key.match(NAME_PERIOD_SUFFIX_RE);
  const res=Object.freeze(m?{base:key.slice(0,-m[0].length),period:periodLabel(m[1])}:{base:key,period:null});
  _stripPeriodCache.set(key,res);
  return res;
}
// Trennt einen Recherche-Wert wie "53.9 (S&P Global/CIPS)" in den reinen
// Wert ("53.9") und die Zusatzinfo aus den Klammern ("S&P Global/CIPS").
// In der Wertezeile steht nur der reine Wert, die Zusatzinfo wandert in
// den aufklappbaren Quellen-Bereich.
// Erkennt zusätzlich, ob der primäre Wert eine Y/Y-, M/M- oder Q/Q-Angabe
// ist (z.B. "4.2% YoY / 0.5% MoM" oder "3.2% (HICP y/y)") und liefert den
// jeweils anderen Zeitraum-Wert separat als "note2" zurück, damit dieser
// nur im aufklappbaren Bereich erscheint und nicht doppelt im Hauptwert
// auftaucht.
function splitResearchVal(s){
  if(s==null)return{val:null,period:null,note2:null,notes:[]};
  const str=String(s).trim();
  let notes=[];
  let val=str.replace(/\s*\(([^)]*)\)/g,(m,g)=>{notes.push(g.trim());return'';}).trim();
  let period=null,note2=null;
  const pm=val.match(new RegExp(`^([+\\-]?[\\d.,]+\\s*%?)\\s*(${PERIOD_TAG_RE.source})\\b\\s*(?:\\/\\s*([+\\-]?[\\d.,]+\\s*%?)\\s*(${PERIOD_TAG_RE.source}))?`));
  if(pm){
    period=periodLabel(pm[2]);
    val=pm[1].trim();
    if(pm[3]&&pm[4])note2={val:pm[3].trim(),period:periodLabel(pm[4])};
  }
  notes=notes.map(n=>{
    const nm=n.match(new RegExp(`^([+\\-]?[\\d.,]+\\s*%?)\\s*(${PERIOD_TAG_RE.source})$`));
    if(nm){
      const p2=periodLabel(nm[2]);
      if(!note2&&p2!==period)note2={val:nm[1].trim(),period:p2};
      return null;
    }
    const lm=n.match(new RegExp(`^(.*\\S)\\s+(${PERIOD_TAG_RE.source})$`));
    if(lm){if(!period)period=periodLabel(lm[2]);return lm[1];}
    const lm2=n.match(new RegExp(`^(${PERIOD_TAG_RE.source})\\s+(.*\\S)$`));
    if(lm2){if(!period)period=periodLabel(lm2[1]);return lm2[2];}
    return n;
  }).filter(Boolean);
  return{val:val||String(s),period,note2,notes};
}

function researchBias(name,actual,forecast,previous){
  const ac=actualColor({name,actual,forecast,previous});
  return ac==='act-good'?'bull':ac==='act-bad'?'bear':'neu';
}
// Einmalige Befüllung: entfernt nicht zutreffende Indikatoren, ergänzt
// fehlende High-Impact-Indikatoren und trägt bei gefundenen Daten den
// letzten bekannten Wert (Akt/Forecast/Previous) + Intervall-Badge ein.
// Läuft pro Symbol nur einmal.
function applyIndResearch(sym){
  if(sym._researchV25)return;
  // Aufräumen: alte "Letzter Wert: ..."-Stichpunkte aus v2 entfernen
  (sym.rubrics||[]).forEach(rub=>{
    (rub.indicators||[]).forEach(ind=>{
      if(ind.points&&ind.points.length)ind.points=ind.points.filter(p=>!/^Letzter Wert:/.test(p.text));
    });
  });
  // Recherchedaten kommen von der verbundenen Währung (Standard USD; bei z.B.
  // mit EUR verbundenen Assets von EUR; "keine Verbindung" -> keine Daten).
  const lc=effLinkCcy(sym);
  const data=lc?(IND_RESEARCH_DATA[lc]||IND_RESEARCH_DATA[sym.id]):null;
  const dispMap=(lc&&IND_DISPLAY_NAMES[lc])||IND_DISPLAY_NAMES[sym.id]||{};
  if(!data){sym._researchV7=true;sym._researchV8=true;sym._researchV9=true;sym._researchV10=true;sym._researchV11=true;sym._researchV12=true;sym._researchV17=true;sym._researchV18=true;sym._researchV19=true;sym._researchV20=true;sym._researchV21=true;sym._researchV22=true;sym._researchV25=true;return;}
  data.entries.forEach(e=>{
    const rub=sym.rubrics.find(r=>r.name===e.rubric);
    if(!rub||!rub.indicators)return;
    // Per Basisnamen matchen (ohne y/y-/m/m-/q/q-Suffix), damit bereits
    // umbenannte Indikatoren (aus einem vorherigen applyIndResearch-Lauf)
    // bei einem erneuten Lauf (Versions-Bump) wiedergefunden werden.
    const idx=rub.indicators.findIndex(i=>stripPeriodSuffix(i.name).base===e.indicator);
    if(!e.applicable){
      if(idx>=0)rub.indicators.splice(idx,1);
      return;
    }
    if(idx<0)return;
    const ind=rub.indicators[idx];
    // Offiziellen, währungsspezifischen Anzeigenamen setzen (Match-Key bleibt).
    if(dispMap[e.indicator])ind.displayName=dispMap[e.indicator];
    if(e.interval)ind.interval=e.interval;
    if(e.actual!=null){
      ind.research={actual:e.actual,forecast:e.forecast,previous:e.previous,date:e.releaseDate,source:e.source,secondarySource:e.secondarySource,secondaryLabel:e.secondaryLabel,unit:e.unit,interval:e.interval};
      ind.bias=researchBias(e.indicator,e.actual,e.forecast,e.previous);
      // Zeigt im Indikator-Namen an, welcher Zeitraum (y/y/m/m/q/q) als
      // Hauptwert dargestellt wird, z.B. "PPI y/y" - der jeweils andere
      // Zeitraum landet (via splitResearchVal) nur in den Details.
      // "period:null" (explizit gesetzt) unterdrückt das Suffix, falls für
      // diesen Datenpunkt kein passender investing.com-Link existiert.
      const per='period'in e?e.period:splitResearchVal(e.actual).period;
      ind.name=per?e.indicator+' '+per.toLowerCase():e.indicator;
    }
  });
  sym._researchV7=true;
  sym._researchV8=true;
  sym._researchV9=true;
  sym._researchV10=true;
  sym._researchV11=true;
  sym._researchV12=true;
  sym._researchV17=true;
  sym._researchV18=true;
  sym._researchV19=true;
  sym._researchV20=true;
  sym._researchV21=true;
  sym._researchV22=true;
  sym._researchV25=true;
}

// ══ DEFAULT DATA ════════════════════════════════════════════════════
function mkInds(names){return names.map(n=>({id:uid(),name:n,bias:'neu',imp:false,date:'',interval:'',points:[]}));}
function mkRubs(){return[
  {id:uid(),name:'Inflation',bias:'neu',imp:false,summary:'',indicators:mkInds(['CPI (Headline)','CPI m/m','Core CPI','PPI','Core PPI','PCE','Core PCE','Services Inflation','Inflation Expectations','2Y Bond Yield','10Y Bond Yield','2Y/10Y Spread'])},
  {id:uid(),name:'Interest Rates',bias:'neu',imp:false,summary:'',indicators:mkInds(['Central Bank Rate','CB Tone','Next CB Move'])},
  {id:uid(),name:'Labour Market',bias:'neu',imp:false,summary:'',indicators:mkInds(['NFP / Employment Change','Unemployment Rate','ADP Employment','JOLTS Job Openings','Avg Hourly Earnings','Unemployment Claims'])},
  {id:uid(),name:'Economic Growth',bias:'neu',imp:false,summary:'',indicators:mkInds(['GDP Growth QoQ','Manufacturing PMI','Services PMI','Retail Sales','Consumer Confidence','ZEW Economic Sentiment','Ifo Business Climate'])},
  {id:uid(),name:'COT Data',bias:'neu',imp:false,summary:'',indicators:mkInds(['Net Bullish Positioning','Net Bearish Positioning','WoW Change in Net Position (%)'])},
];}
// Globale, für alle Symbole gleiche Rubrik-Reihenfolge. Wird beim
// Verschieben einer Karte (mvRub) aktualisiert und auf alle Symbole
// angewendet, damit überall die gleiche Kartenreihenfolge gilt.
// Globale Kartenreihenfolge der Makro-Kategorien (für jedes Symbol gleich):
// Inflation, Leitzins, Arbeitsmarkt, Wirtschaftswachstum, COT Data, Risk
// Environment (Nutzer-Wunsch 2026-07-13: als LETZTE Karte).
function mkRubOrder(){return['Inflation','Interest Rates','Labour Market','Economic Growth','COT Data',MACRO_NAME];}
// Kurze englische Standard-Erklärung pro Indikator (Basisname ohne y/y-Suffix):
// was/wen er misst, wie er angegeben ist, was er bedeutet. Wird schreibgeschützt
// im Info-Fenster ("i") über den eigenen Notizen angezeigt.
