// ══ MAKRO & RISIKOUMFELD (zusätzliche Rubrik) ════════════════════════
const MACRO_NAME='Risk Environment';
const MACRO_NAME_LEGACY='Makro & Risikoumfeld';
// Alter englischer Name vor der Umbenennung (Nutzer-Wunsch 2026-07-13:
// "Macro & Risk Environment" -> "Risk Environment", nur noch 2 Indikatoren
// Risk Correlation + Geopolitics, Karte ans Ende verschoben). Wird wie
// MACRO_NAME_LEGACY beim Laden/Sync mitgezogen.
const MACRO_NAME_LEGACY2='Macro & Risk Environment';
// Diese Rubriken werden zwischen USD und allen USD-getriebenen Assets
// (Rohstoffe, Krypto, Indizes) synchron gehalten – siehe syncMacroRub().
const MACRO_SYNC_RUBS=['Interest Rates','Inflation','Labour Market',MACRO_NAME];
// Leitet Rubrik- und Indikator-Bias (Karte + jeder einzelne Indikator) eines
// Nicht-FX-Assets automatisch aus der verbundenen Währung ab, statt es manuell
// einzutragen. Pro Rubrik: 'same' = starke Daten gelten als bullish (identisch
// zur Währung), 'inverse' = starke Daten gelten als bearish (umgekehrt),
// 'off'/fehlend = manuell (keine Ableitung). Einstellbar pro Asset über das
// Zahnrad-Menü (sym.deriveRules). MACRO_DERIVE_RULES sind nur die VORGABEN für
// die eingebauten Assets Gold/S&P 500/Nasdaq.
const MACRO_DERIVE_RUBS=['Inflation','Interest Rates','Labour Market','Economic Growth'];
const MACRO_DERIVE_RULES={
  GOLD:{Inflation:'inverse','Interest Rates':'inverse','Labour Market':'inverse','Economic Growth':'same'},
  SP500:{Inflation:'inverse','Interest Rates':'inverse','Labour Market':'same','Economic Growth':'same'},
  NAS:{Inflation:'inverse','Interest Rates':'inverse','Labour Market':'same','Economic Growth':'same'},
};
// Yields-Kategorie (Nutzer-Wunsch 2026-08-24, woertlich: "mach interest
// rates bullish, inflation bullish, labourmarket bullish, economic groth
// bullish") - alle vier Makro-Rubriken 'same': starke Daten (heisse
// Inflation, robuster Arbeitsmarkt, hawkishe Zinserwartung, starkes
// Wachstum) gelten fuer ein Yield-Asset als bullish, exakt wie fuer die
// zugrundeliegende Waehrung selbst - ein Yield-Asset IST im Kern die
// Zinserwartung dieser Waehrung.
Object.keys(YIELD_CCY).forEach(id=>{
  MACRO_DERIVE_RULES[id]={Inflation:'same','Interest Rates':'same','Labour Market':'same','Economic Growth':'same'};
});
function invertBias(b){return b==='bull'?'bear':b==='bear'?'bull':'neu';}
// Effektive Auto-Bias-Regeln eines Assets: explizit gesetzte sym.deriveRules,
// sonst die Vorgabe für die eingebauten Assets, sonst keine (alles manuell).
function effDeriveRules(sym){
  if(sym&&sym.deriveRules)return sym.deriveRules;
  return(sym&&MACRO_DERIVE_RULES[sym.id])||{};
}
function deriveMacroBiasAll(){
  syms.forEach(sym=>{
    if(!isNonFx(sym.id)||!sym.rubrics)return;
    const ccy=macroCcyFor(sym.id);if(!ccy)return; // keine Verbindung -> alles manuell
    const srcSym=syms.find(s=>s.id===ccy);if(!srcSym||!srcSym.rubrics)return;
    const rules=effDeriveRules(sym);
    sym.rubrics.forEach(r=>{
      // NUR die 4 echten Makro-Karten duerfen von der Waehrung abgeleitet
      // werden (Nutzer-Bugreport 2026-07-21: COT Data/Risk Environment sind
      // asset-eigene Daten, komplett unabhaengig von der verknuepften
      // Waehrung - eine same/inverse-Regel darauf ueberschreibt faelschlich
      // den echten, aus den eigenen Daten berechneten Bias, z.B. GOLDs
      // eigener COT-Report durch den invertierten USD-COT-Bias).
      if(!MACRO_DERIVE_RUBS.includes(r.name))return;
      const rule=rules[r.name];
      if(rule!=='same'&&rule!=='inverse')return;
      const src=srcSym.rubrics.find(x=>x.name===r.name);if(!src)return;
      r.bias=rule==='same'?src.bias:invertBias(src.bias);
      if(r.indicators&&src.indicators)r.indicators.forEach(ind=>{
        const srcInd=src.indicators.find(i=>i.name===ind.name);if(!srcInd)return;
        ind.bias=rule==='same'?srcInd.bias:invertBias(srcInd.bias);
        // Trend-Anteil (Chip + Score-Bonus) ebenfalls spiegeln, nicht nur das
        // Basis-Bias - sonst fehlt Non-FX-Assets (Gold, Oel, Indizes ...) die
        // Trend-Kategorie komplett, obwohl ihr Score sonst 1:1 von der
        // verknuepften Waehrung abgeleitet wird. Richtung (bull/bear) wird wie
        // beim Bias selbst gespiegelt/invertiert; die zugrundeliegenden
        // Rohwerte (valHist/valDates/trendCmp) bleiben unveraendert - das sind
        // die echten Konjunkturdaten der Waehrung, nur ihre Interpretation als
        // bullish/bearish fuer DIESES Asset kann sich umkehren.
        ind.trendDriven=!!srcInd.trendDriven;
        ind.stepDriven=!!srcInd.stepDriven;
        ind.trendBias=srcInd.trendBias&&srcInd.trendBias!=='neu'?(rule==='same'?srcInd.trendBias:invertBias(srcInd.trendBias)):'neu';
        if(Array.isArray(srcInd.valHist))ind.valHist=srcInd.valHist.slice();
        if(Array.isArray(srcInd.valDates))ind.valDates=srcInd.valDates.slice();
        if(srcInd.trendCmp)ind.trendCmp=srcInd.trendCmp.slice();
      });
    });
  });
}
