function mkNCs(){return[
  {id:uid(),name:'Macro Overview',items:[{id:uid(),text:'Global risk sentiment',imp:false},{id:uid(),text:'Fed rate path expectations',imp:false}]},
  {id:uid(),name:'Geopolitics',items:[{id:uid(),text:'Middle East: Hormuz tensions',imp:true}]},
];}
// ══ RESEARCH LIBRARY (Nutzer-Wunsch 2026-08-02) ══════════════════
// Loest den frueheren "Notes"-Tab ab: statt einer flachen Kategorie->Zeilen-
// Liste jetzt ein Dokumentationswerkzeug zum Festhalten von Markterfahrungen
// mit ZWEI unabhaengigen Ordnungsachsen:
//   TOPICS  - vom Nutzer angelegte Themen-Ordner (note.fid)
//   ASSETS  - automatisch aus note.asset abgeleitet (kein eigener Ordner
//             noetig, jede Notiz kann optional einem Asset zugeordnet werden)
// plus Favoriten-Filter, Freitext-Tags (#inflation ...) und Volltextsuche.
// Teil von snap() (Undo + Cloud-Sync laufen dadurch automatisch mit, siehe
// CLAUDE.md "WICHTIGSTE REGEL" - kein eigener 4-Punkte-Sync noetig).
const RESEARCH_FOLDER_ICONS=['bars','trendUp','zap','flame','shuffle'];
// Feste Asset-Kategorie-Ordner (Nutzer-Wunsch 2026-08-03: "genau diese 5
// Ordner, alle anderen entferne ich" - ersetzt die fruehere frei anlegbare
// Themen-Ordner-Struktur). IDs sind bewusst FEST/stabil (nicht uid()), damit
// researchFolderIdFor() sie referenzieren kann - nicht umbenennbar/loeschbar.
const RESEARCH_ASSET_FOLDERS=[
  {id:'fx',name:'FX',icon:'shuffle'},
  {id:'indices',name:'Indices',icon:'bars'},
  {id:'commodities',name:'Commodities',icon:'flame'},
  {id:'crypto',name:'Crypto',icon:'zap'},
  {id:'stocks',name:'Stocks',icon:'trendUp'},
];
function mkResearchFolders(){return RESEARCH_ASSET_FOLDERS.map(f=>({...f}));}
function mkResearch(){return{folders:mkResearchFolders(),notes:[],_folderSchemaV:2};}
// Asset-ID -> fester Research-Ordner, rein aus der Asset-Klasse abgeleitet
// (ASSET_CLASS/customIds via assetCls) - KEIN zusaetzlicher State noetig:
// ein neu ueber "+ Add Symbol" angelegtes Asset erscheint dadurch automatisch
// im richtigen Ordner (Nutzer-Wunsch: "sobald ein Asset hinzugefuegt wird,
// passiert das gleiche bei der Research-Kategorie").
function researchFolderIdFor(id){
  if(FX.includes(id))return'fx';
  const cls=assetCls(id);
  if(cls==='crypto')return'crypto';
  if(cls==='metal'||cls==='energy')return'commodities';
  if(cls==='index')return'indices';
  if(cls==='stock')return'stocks';
  return null;
}
function researchAssetsIn(fid){return (syms||[]).filter(s=>researchFolderIdFor(s.id)===fid);}
// ══ RESEARCH-ORDNERBAUM (Nutzer-Wunsch 2026-08-04) ══════════════════════
// Ersetzt den bisherigen "Assets"/"Notes"-Umschalter (renderResearchFolders/
// renderResearchNotes, beide bleiben als Code stehen, aber werden vom neuen
// Einstiegspunkt nicht mehr aufgerufen - der Nutzer hat explizit angekuendigt,
// als naechstes zu spezifizieren, was auf der rechten Seite erscheinen soll,
// moeglicherweise unter Wiederverwendung dieser Funktionen) durch EINEN
// durchgehenden, klappbaren Ordnerbaum wie im Windows-Explorer:
//   Wurzel: die 5 festen RESEARCH_ASSET_FOLDERS-Kategorien + benutzerdefinierte
//           Top-Level-Ordner (researchFolders mit parentId:null)
//   Kategorie-Ordner: automatisch aus den Assets abgeleitete Asset-Ordner
//           (researchAssetsIn, KEIN eigener Speicher noetig - ein neues Asset
//           erscheint automatisch) + benutzerdefinierte Unterordner
//   Asset-Ordner: GENAU 2 feste Blaetter "General Notes"/"Analysis" - keine
//           benutzerdefinierten Kinder dort (Nutzer-Wunsch: "und das war's")
//   Benutzerdefinierter Ordner: beliebig tief verschachtelbare weitere
//           benutzerdefinierte Unterordner
// researchFolders speichert NUR die benutzerdefinierten Knoten (id/name/
// parentId) - alles Abgeleitete wird bei jedem Render frisch berechnet,
// genau wie researchFolderIdFor() das schon fuer die Kategorie-Zuordnung tut.
function researchCustomChildren(parentId){return (researchFolders||[]).filter(f=>f.parentId===parentId);}
function researchChildrenOf(type,id){
  if(type==='root'){
    return RESEARCH_ASSET_FOLDERS.map(f=>({id:f.id,name:f.name,icon:f.icon,type:'cat'}))
      .concat(researchCustomChildren(null).map(f=>({id:f.id,name:f.name,icon:'folder',type:'custom'})));
  }
  if(type==='cat'){
    const assets=researchAssetsIn(id).slice().sort((a,b)=>a.name.localeCompare(b.name));
    return assets.map(s=>({id:'asset:'+s.id,name:s.name,icon:'folder',type:'asset'}))
      .concat(researchCustomChildren(id).map(f=>({id:f.id,name:f.name,icon:'folder',type:'custom'})));
  }
  if(type==='asset'){
    // "General Notes" ist jetzt selbst ein aufklappbarer Knoten (eigene
    // Unterordner zum Gliedern der Notizen, Nutzer-Wunsch 2026-08-04:
    // "wichtig das man die Notizen auch nochmal in Ordner gliedern kann") -
    // "Analysis" bleibt ein reines Blatt (eigene Gliederung nach Karten,
    // siehe researchAnalysisPanelHtml()).
    return[
      {id:id+':gen',name:'General Notes',icon:'note',type:'notesRoot'},
      {id:id+':analysis',name:'Analysis',icon:'trendUp',type:'analysis'},
    ];
  }
  if(type==='custom'){
    return researchCustomChildren(id).map(f=>({id:f.id,name:f.name,icon:'folder',type:'custom'}));
  }
  if(type==='notesRoot'||type==='notesFolder'){
    return researchCustomChildren(id).map(f=>({id:f.id,name:f.name,icon:'folder',type:'notesFolder'}));
  }
  return[];
}
function researchAllFolderIds(){
  const ids=[];
  (function walk(type,id){
    researchChildrenOf(type,id).forEach(k=>{if(k.type!=='analysis'){ids.push(k.id);walk(k.type,k.id);}});
  })('root',null);
  return ids;
}
function researchFolderById(id){return (researchFolders||[]).find(f=>f.id===id);}
// Loest einen ausgewaehlten Baum-Knoten auf die Notizen-Ordner-Kontext auf
// (Asset + Ordner-ID), falls es sich um die "General Notes"-Wurzel oder
// einen (beliebig tief verschachtelten) eigenen Unterordner darunter
// handelt - sonst null (z.B. bei Kategorie-/Asset-/eigenen Top-Level-
// Ordnern, fuer die noch kein rechter Inhalt definiert ist).
function researchNotesContextFor(selId){
  if(!selId)return null;
  const m=/^asset:(.+):gen$/.exec(selId);
  if(m)return{assetId:m[1],fid:null};
  let cur=researchFolderById(selId);
  if(!cur)return null;
  let p=cur.parentId,walked=0;
  while(p&&walked<50){
    const gm=/^asset:(.+):gen$/.exec(p);
    if(gm)return{assetId:gm[1],fid:selId};
    const parentFolder=researchFolderById(p);
    if(!parentFolder)break;
    p=parentFolder.parentId;walked++;
  }
  return null;
}
// Transiente UI-Zustaende (Auf-/Zuklapp-Status pro Knoten, aktuell markiertes
// Blatt) - bewusst NICHT persistiert, gleiches Muster wie indDetailsOpen{}/
// dashEditMode (App-Grundsatz: reiner Navigations-/Sitzungszustand).
let researchTreeOpen={},researchTreeSel=null;
// Research-Terminal (Nutzer-Wunsch 2026-08-04, Referenz-Screenshots):
// researchFocusAsset = das Asset, das die 5 Top-Karten + die Timeline-Spalte
// zeigen (gesetzt durch Klick auf einen Asset-Ordner im Baum) - genau wie
// dataAsset/seasAsset an anderer Stelle bewusst NICHT persistiert (reiner
// Anzeige-Zustand, kein Nutzer-Inhalt). researchTopOpen haelt fest, welche
// der 5 Karten gerade aufgeklappt ist (immer nur eine, wie ein Akkordeon -
// sonst wuerde die Kartenreihe bei mehreren offenen Tabellen zu hoch/
// unuebersichtlich). resTreeCollapsed klappt die Sidebar auf einen
// schmalen Pfeil-Streifen ein.
let researchFocusAsset=null,researchTopOpen=null,resTreeCollapsed=false,_resReturnActive=false;
// Ziel der roten Zurueck-Pille (Nutzer-Wunsch 2026-08-23): null = zurueck ins
// Research-Terminal (alter, alleiniger Fall), sonst eine Asset-ID = zurueck
// auf die Assets-Detailseite dieses Assets (neuer Quick-Links-Weg von dort,
// siehe assetQuickGo). Rein transienter Navigations-Zustand, kein Sync noetig.
let _quickReturnAssetId=null;
function researchToggleNode(id){researchTreeOpen[id]=!researchTreeOpen[id];rerenderNotesHost();}
function researchSelectLeaf(id){researchTreeSel=id;rerenderNotesHost();}
// Klick auf einen Asset-Ordner: klappt wie jeder andere Knoten auf/zu UND
// macht dieses Asset zum Fokus der Top-Karten/Timeline (Referenz-Foto zeigt
// diese Karten IMMER fuer "das gerade betrachtete Asset").
function researchSelectAsset(nodeId){
  researchTreeOpen[nodeId]=!researchTreeOpen[nodeId];
  researchFocusAsset=nodeId.slice(6); // 'asset:EUR' -> 'EUR'
  // renderRub()/getRub()/getSym() haengen an selId - synchron halten, damit
  // die 1:1 wiederverwendete Rubrik-Karte (researchTopCardsHtml) exakt den
  // Fokus-Asset trifft, sobald der Nutzer eine der 5 Karten aufklappt.
  selId=researchFocusAsset;
  researchTopOpen=null;
  rerenderNotesHost();
}
// Notizen-Ordner (General-Notes-Wurzel + eigene Unterordner) sind gleich-
// zeitig aufklappbar UND ausgewaehlt (zeigt direkt seine eigenen Notizen
// rechts an, wie ein Ordner im Windows-Explorer, der per Klick sowohl
// aufklappt als auch seinen Inhalt anzeigt).
function researchSelectAndToggle(id){
  researchTreeSel=id;
  researchTreeOpen[id]=!researchTreeOpen[id];
  rerenderNotesHost();
}
function researchExpandAllToggle(){
  const anyOpen=researchAllFolderIds().some(id=>researchTreeOpen[id]);
  if(anyOpen)researchTreeOpen={};
  else researchAllFolderIds().forEach(id=>researchTreeOpen[id]=true);
  rerenderNotesHost();
}
// Neuen benutzerdefinierten Ordner anlegen - unter der Wurzel (parentId:null,
// "grosser" Top-Level-Ordner) oder unter einer Kategorie/einem anderen
// benutzerdefinierten Ordner (Unterordner). Kategorie- und Asset-Ordner sowie
// die beiden festen Blaetter sind bewusst NICHT anlegbar/loeschbar - nur
// benutzerdefinierte Knoten sind es (matcht "und das war's" fuer die feste
// Struktur, waehrend eigene Ordner "beliebig oft" hinzufuegbar bleiben).
function researchAddFolder(parentId){
  const name=prompt(parentId?'Name of the new subfolder:':'Name of the new folder:');
  if(!name||!name.trim())return;
  pushU();
  researchFolders.push({id:uid(),name:name.trim().slice(0,60),parentId:parentId||null});
  if(parentId)researchTreeOpen[parentId]=true;
  save();rerenderNotesHost();
}
function researchDelFolder(id){
  if(!confirm('Delete this folder and all its subfolders?'))return;
  pushU();
  // Kaskadierendes Loeschen: sonst wuerden verschachtelte Unterordner als
  // erreichbare, aber elternlose Knoten im Speicher haengen bleiben.
  const doomed=new Set([id]);
  let grew=true;
  while(grew){
    grew=false;
    researchFolders.forEach(f=>{if(f.parentId&&doomed.has(f.parentId)&&!doomed.has(f.id)){doomed.add(f.id);grew=true;}});
  }
  researchFolders=researchFolders.filter(f=>!doomed.has(f.id));
  delete researchTreeOpen[id];
  if(researchTreeSel&&doomed.has(researchTreeSel.split(':')[0]))researchTreeSel=null;
  save();rerenderNotesHost();
}
// 5s-Long-Press -> Bearbeitungsmodus (identisches Muster zu dashEditMode/
// indEditMode, siehe dort) - erst im Bearbeitungsmodus erscheinen die
// +/×-Knoepfe zum Hinzufuegen/Loeschen eigener Ordner.
let resEditMode=false,_resEditTimer=null,_resEditStart=null;
function resEditPressStart(ev){
  if(ev.button!==undefined&&ev.button!==0)return;
  if(ev.target.closest('button,input,textarea,select,a'))return;
  if(_resEditTimer)clearTimeout(_resEditTimer);
  _resEditStart={x:ev.clientX,y:ev.clientY};
  _resEditTimer=setTimeout(()=>{_resEditTimer=null;toggleResEditMode();},5000);
}
function resEditPressMove(ev){
  if(!_resEditTimer||!_resEditStart)return;
  if(Math.abs(ev.clientX-_resEditStart.x)>14||Math.abs(ev.clientY-_resEditStart.y)>14){clearTimeout(_resEditTimer);_resEditTimer=null;}
}
function resEditPressEnd(){if(_resEditTimer){clearTimeout(_resEditTimer);_resEditTimer=null;}}
function toggleResEditMode(){
  resEditMode=!resEditMode;
  document.body.classList.toggle('res-edit-mode',resEditMode);
  if(navigator.vibrate)try{navigator.vibrate(resEditMode?[25,35,25]:20);}catch(e){}
}
function researchNodeRow(node,depth){
  const open=!!researchTreeOpen[node.id];
  const hasKids=node.type!=='analysis';
  const isNotes=node.type==='notesRoot'||node.type==='notesFolder';
  const isCustom=node.type==='custom'||node.type==='notesFolder';
  const canAddChild=node.type==='cat'||node.type==='custom'||isNotes;
  const selCls=(researchTreeSel===node.id||(node.type==='asset'&&researchFocusAsset===node.id.slice(6)))?' on':'';
  const kids=hasKids&&open?researchChildrenOf(node.type,node.id):[];
  const onclick=node.type==='analysis'?`researchSelectLeaf('${node.id}')`
    :isNotes?`researchSelectAndToggle('${node.id}')`
    :node.type==='asset'?`researchSelectAsset('${node.id}')`
    :`researchToggleNode('${node.id}')`;
  return`<div class="rtree-node">
    <div class="rtree-row${selCls}" style="padding-left:${10+depth*20}px" onclick="${onclick}">
      <span class="rtree-toggle">${hasKids?(open?'▾':'▸'):''}</span>
      <span class="rtree-ic">${icn(node.icon,14)}</span>
      <span class="rtree-nm">${escH(node.name)}</span>
      <span class="rtree-edit-ctrls">
        ${canAddChild?`<button class="rtree-add" title="Add subfolder" onclick="event.stopPropagation();researchAddFolder('${node.id}')">+</button>`:''}
        ${isCustom?`<button class="rtree-del" title="Delete folder" onclick="event.stopPropagation();researchDelFolder('${node.id}')">×</button>`:''}
      </span>
    </div>
    ${kids.length?`<div class="rtree-children">${kids.map(k=>researchNodeRow(k,depth+1)).join('')}</div>`:''}
  </div>`;
}
// Titel aus einem alten Freitext-Eintrag ableiten: erste Zeile, auf eine
// lesbare Laenge gekuerzt. Der VOLLE Text bleibt immer im Body erhalten -
// es geht bei der Migration nichts verloren.
function researchTitleFrom(text){
  const first=String(text||'').split(/\r?\n/)[0].trim();
  if(!first)return 'Untitled note';
  return first.length>90?first.slice(0,90).trim()+'…':first;
}
// Einmalige, verlustfreie Migration der alten noteCats-Struktur. `noteCats`
// selbst wird dabei BEWUSST nicht angetastet und bleibt weiter Teil von
// snap() - faellt bei der Migration etwas auf die Nase, sind die
// Originaldaten noch vollstaendig vorhanden.
function migrateResearch(r,legacyCats){
  if(!r||!Array.isArray(r.folders)||!Array.isArray(r.notes)){
    r=mkResearch();
    if(Array.isArray(legacyCats)&&legacyCats.length){
      const nowIso=new Date().toISOString();
      // Alte noteCats-Eintraege werden als unfiled-Notizen uebernommen (kein
      // Datenverlust) - eigene Themenordner dafuer gibt es nicht mehr (siehe
      // migrateResearchToAssetFolders unten).
      legacyCats.forEach(c=>{
        (c&&c.items||[]).forEach(it=>{
          r.notes.push({id:uid(),fid:'',title:researchTitleFrom(it&&it.text),
            body:String(it&&it.text||''),tags:[],asset:'',fav:!!(it&&it.imp),ts:nowIso,up:nowIso});
        });
      });
    }
  }
  return migrateResearchToAssetFolders(r);
}
// Einmalige Migration (Nutzer-Wunsch 2026-08-03): die fruehere freie Themen-
// Ordner-Struktur (beliebig viele, per "+Add topic" erweiterbar) wird durch
// genau 5 feste Asset-Kategorie-Ordner ersetzt. Notizen aus jetzt entfernten
// Ordnern werden NICHT geloescht, sondern auf fid='' (Unfiled) umgehaengt -
// kein Datenverlust, nur die Ordnerzuordnung geht verloren. Ueber
// _folderSchemaV idempotent (laeuft nur einmal pro Nutzer).
function migrateResearchToAssetFolders(r){
  if(r._folderSchemaV===2)return r;
  const validIds=new Set(RESEARCH_ASSET_FOLDERS.map(f=>f.id));
  (r.notes||[]).forEach(n=>{if(n.fid&&!validIds.has(n.fid))n.fid='';});
  r.folders=mkResearchFolders();
  r._folderSchemaV=2;
  return r;
}
// Keine fest einprogrammierten Beispiel-Events mehr: der Kalender wird
// ausschließlich live von Forex Factory befüllt (autoFetchFF beim Laden +
// Refresh-Button), damit keine redaktionellen Platzhalter wie "95% priced"
// erscheinen. Frühere Seed-Events werden bei Bestandsnutzern einmalig per
// cleanLegacySeedEvts() entfernt.
const LEGACY_SEED_EVTS=['US NFP','ECB Rate Decision','RBA Rate Decision','BoJ Rate Decision','RBNZ Rate Decision'];
function mkCalEvts(){return[];}
function cleanLegacySeedEvts(){
  if(localStorage.getItem('fxpro_seedclean')==='1')return false;
  const set=new Set(LEGACY_SEED_EVTS);
  const before=calEvts.length;
  // Nur die alten, von uns gesetzten Seed-Events treffen: kein FF-Import,
  // noch kein Actual und mit redaktionellem expected-Text.
  calEvts=calEvts.filter(e=>!(e.src!=='ff'&&!e.actual&&set.has(e.name)&&(e.expected||'')));
  localStorage.setItem('fxpro_seedclean','1');
  return calEvts.length!==before;
}
