// ══ LOCK SCREEN ══════════════════════════════════════════════════
// Nur der SHA-256-Hash der PIN steht im (oeffentlichen!) Repo - der
// Klartext laesst sich daraus nicht ablesen. Bleibt trotzdem nur ein
// Basis-Schutz gegen Schulterblicke, kein echter Zugriffsschutz (die
// Daten selbst liegen unverschluesselt in localStorage).
const LOCK_HASH='9552e277ebcc7fa191292c6e900d94dfe6e837d8abf76a2da927d4530d2c8f69';
// Ob die PIN-Sperre ueberhaupt aktiv ist (Schalter im Cloud-Sync-Panel, neben
// dem Banner-Ein/Aus). Liegt bewusst ausserhalb von snap()/Undo (wie
// tabStacks), muss aber trotzdem geraeteuebergreifend
// synchron sein - deshalb die volle Vier-Punkte-Anbindung (cloudPush/
// cloudPull/Save-Bump/Export-Import). Der frueheste Boot-Check (ganz oben in
// index.html, direkt nach #lockScreen) liest denselben localStorage-Schluessel,
// damit der Sperrbildschirm bei deaktivierter PIN gar nicht erst aufblitzt.
let pinEnabled=localStorage.getItem('fxpro_pin_enabled')!=='0';
function updPinToggleBtn(){const btn=document.getElementById('pinToggleBtn');if(btn)btn.checked=pinEnabled;}
function togglePinEnabled(){
  pinEnabled=!pinEnabled;
  try{localStorage.setItem('fxpro_pin_enabled',pinEnabled?'1':'0');}catch(e){}
  localStorage.setItem('fxpro_updated',new Date().toISOString());
  _lsUpdatedSeen=localStorage.getItem('fxpro_updated');
  markPrefEdit();
  cloudAutoSync();
  updPinToggleBtn();
  // Beim Deaktivieren sofort entsperren (kein Reload noetig, kein
  // ueberraschendes erneutes Sperren mitten in der Sitzung beim Aktivieren).
  if(!pinEnabled){
    try{sessionStorage.setItem('fxpro_unlocked','1');}catch(e){}
    const ov=document.getElementById('lockScreen');if(ov)ov.style.display='none';
  }
}
// Nutzer-Wunsch 2026-08-04 ("genau wie den Code aktivieren/deaktivieren
// koennen, direkt unter dem Code"): identisches An/Aus-Muster wie
// pinEnabled direkt darueber - liegt bewusst ausserhalb von snap()/Undo
