async function checkLockCode(code){
  try{
    const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(code));
    return[...new Uint8Array(buf)].map(b=>b.toString(16).padStart(2,'0')).join('')===LOCK_HASH;
  }catch(e){return false;}
}
let lockBuf='';
function lockKey(d){
  if(lockBuf.length>=4)return;
  lockBuf+=d;
  document.getElementById('lockErr').textContent='';
  updLockDots();
  if(lockBuf.length===4){
    checkLockCode(lockBuf).then(ok=>{
      if(ok){
        sessionStorage.setItem('fxpro_unlocked','1');
        setTimeout(unlockApp,150);
      }else{
        document.getElementById('lockErr').textContent='Wrong code';
        const box=document.getElementById('lockBox');
        box.classList.add('shake');
        setTimeout(()=>{box.classList.remove('shake');lockBuf='';updLockDots();},400);
      }
    });
  }
}
function lockBack(){lockBuf=lockBuf.slice(0,-1);document.getElementById('lockErr').textContent='';updLockDots();}
function updLockDots(){
  document.querySelectorAll('#lockDots .lock-dot').forEach((el,i)=>el.classList.toggle('filled',i<lockBuf.length));
}
function unlockApp(){
  const ov=document.getElementById('lockScreen');
  ov.style.opacity='0';
  setTimeout(()=>{ov.style.display='none';},300);
}
document.addEventListener('keydown',e=>{
  const ov=document.getElementById('lockScreen');
  if(!ov||ov.style.display==='none')return;
  if(e.key>='0'&&e.key<='9')lockKey(e.key);
  else if(e.key==='Backspace')lockBack();
});

// ══ AUTO-SAVE SAFETY NET ═══════════════════════════════════════════
// oninput handlers already write every keystroke into the in-memory
// state, so save() (which serializes that state) is always up to date.
// We must NOT blur the focused field here - doing so on the periodic
// timer used to kick users out of whatever they were typing.
function flushAndSave(){
  save();
  // Nutzer-Bugreport 2026-08-22 ("Telegram kommt trotz Aus-Schalter"):
  // cloudAutoSync() debounced jeden Auto-Push um 1,5s. Wird die App/der Tab
  // in genau diesem Fenster geschlossen oder in den Hintergrund gelegt (der
  // naheliegendste Ablauf: Schalter umlegen, App sofort zuklappen), verfaellt
  // der Timer ungenutzt - die Aenderung erreicht die Cloud nie, und die
  // serverseitigen Workflows (event-alerts/morning-report/weekly-report)
  // lesen bewusst fail-open weiter den alten (falschen) Stand. Beim
  // tatsaechlichen Verstecken/Verlassen der Seite deshalb den Debounce
  // ueberspringen und sofort pushen, statt auf den Timer zu warten.
  if(_cloudPushTimer){
    clearTimeout(_cloudPushTimer);
    _cloudPushTimer=null;
    cloudPush(false);
  }
}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')flushAndSave();});
window.addEventListener('pagehide',flushAndSave);
window.addEventListener('beforeunload',flushAndSave);
setInterval(flushAndSave,15000);

// ══ MULTI-TAB- & AUFWACH-SYNC ═══════════════════════════════════════
// Mehrere offene Tabs derselben App teilen sich localStorage, hatten aber
// bisher voellig unabhaengige In-Memory-Staende: der 15s-Sicherheitsnetz-Save
// eines aelteren Hintergrund-Tabs hat den neueren Stand des aktiven Tabs
// lokal UND (via Auto-Push) in der Cloud ueberschrieben - Aenderungen waren
// dann "nach mehrmaligem Aktualisieren ploetzlich weg". Drei Schutzschichten:
// (a) storage-Listener: fremde Saves live uebernehmen (Events feuern nur in
//     anderen Tabs als dem schreibenden - genau richtig dafuer),
// (b) save()-Guard (siehe oben): ein Tab, der ein fremdes Update verpasst
//     hat (z.B. von iOS eingefroren), uebernimmt es beim naechsten
//     Hintergrund-Save statt es zu ueberschreiben,
// (c) Aufwachen (Tab wieder sichtbar/bfcache-Restore): erst fremden lokalen
//     Stand uebernehmen, dann Cloud-Abgleich (Push-vor-Pull wie beim Boot).
window.addEventListener('storage',e=>{
  if(e.key!==SK&&e.key!=='fxpro_updated')return;
  const cur=localStorage.getItem('fxpro_updated');
  if(cur===_lsUpdatedSeen)return;
  // Nicht mitten in eine aktive Bearbeitung in DIESEM Tab graetschen -
  // dann gewinnt beim naechsten save() ohnehin die juengste Nutzeraktion.
  if(Date.now()-_lastUserEditTs<3000)return;
  adoptExternalState();
});
let _syncNowBusy=false;
async function cloudSyncNow(){
  if(_syncNowBusy||!getCloudCfg())return;
  _syncNowBusy=true;
  try{
    const pending=localStorage.getItem('fxpro_updated');
    const seen=localStorage.getItem('fxpro_cloud_seen');
    if(pending&&pending!==seen){if(!(await cloudPush(false)))return;}
    await cloudPull(false);
  }finally{_syncNowBusy=false;}
}
let _hiddenAt=0;
document.addEventListener('visibilitychange',()=>{
  if(document.visibilityState==='hidden'){_hiddenAt=Date.now();return;}
  if(localStorage.getItem('fxpro_updated')!==_lsUpdatedSeen)adoptExternalState();
  // Cloud-Abgleich nur nach laengerer Abwesenheit (>30s) - kurze App-Wechsel
  // sollen nicht bei jedem Zurueckkommen einen Netz-Roundtrip ausloesen.
  if(_hiddenAt&&Date.now()-_hiddenAt>30000)cloudSyncNow();
});
// iOS Safari stellt Seiten beim Zurueck-Navigieren/Tab-Wechsel oft aus dem
// bfcache wieder her: der JS-Zustand ist dann so alt wie der Moment des
// Einfrierens, waehrend localStorage/Cloud laengst weiter sind.
window.addEventListener('pageshow',e=>{
  if(!e.persisted)return;
  if(localStorage.getItem('fxpro_updated')!==_lsUpdatedSeen)adoptExternalState();
  cloudSyncNow();
});

// Re-render only when the masonry column count actually changes (e.g.
// rotating a tablet across the 1100px/1600px breakpoints) - never on
// height changes from typing, so cards never jump while editing.
let _masonryCols=masonryCols(),_ovCols=ovCols(),_masonryResizeT=null;
window.addEventListener('resize',()=>{
  clearTimeout(_masonryResizeT);
  _masonryResizeT=setTimeout(()=>{
    const n=masonryCols(),o=ovCols();
    if(n!==_masonryCols||o!==_ovCols){_masonryCols=n;_ovCols=o;renderDetail();}
  },150);
});

// Im Hintergrund laeuft nichts. Der Browser drosselt zwar von sich aus,
// aber nicht bei einem sichtbaren Fenster im zweiten Bildschirm.
document.addEventListener('visibilitychange',()=>{
  document.body.classList.toggle('anim-paused',document.hidden);
});

